def count_word_lengths(words: list[str]) -> dict[int, int]:
    """Return a dictionary mapping each word length to the number of words with that length.

    >>> count_word_lengths(["a", "bb", "cc", "ddd"])
    {1: 1, 2: 2, 3: 1}
    >>> count_word_lengths([])
    {}
    """
    result: dict[int, int] = {}
    for word in words:
        length = len(word)
        result[length] = result.get(length, 0) + 1
    return result
```

