def group_and_rank(scores: list[dict]) -> dict[str, list[str]]:
    """Group names by score and rank them alphabetically within each group.

    Each input dict has keys 'name' (str) and 'score' (int). Return a dict
    mapping the string form of each score to a sorted list of names that
    achieved it. Scores with no entries are omitted.

    Examples:
        >>> group_and_rank([{'name': 'b', 'score': 2}, {'name': 'a', 'score': 2}])
        {'2': ['a', 'b']}
        >>> group_and_rank([{'name': 'x', 'score': 1}, {'name': 'y', 'score': 3}])
        {'1': ['x'], '3': ['y']}
    """
    groups: dict[str, list[str]] = {}
    for entry in scores:
        key = str(entry['score'])
        groups.setdefault(key, []).append(entry['name'])
    return {key: sorted(names) for key, names in groups.items()}
